const aRollSample={speaker:'Fictional adult presenter; no real-person imitation',targetSeconds:45,timingStatus:'Draft timing target, not a measured voice take',facts:'Source method: identify the customer question, use supplied facts, prepare a draft, review claims and ask for the decision. No client result is supplied.',segments:[{from:0,to:5,spoken:'Too many marketing ideas, and no clear next step?',camera:'Eye-level medium close-up; direct and conversational'}, {from:5,to:17,spoken:'Start with one question: what does your customer need to understand before they can enquire? Gather the facts you already have.',camera:'Same eye line; natural pause after the question'}, {from:17,to:31,spoken:'Choose one useful message, and build a small draft around it. Then check every claim, show the draft to the person who can decide, and record what still needs evidence.',camera:'One restrained hand gesture; no fabricated customer footage'}, {from:31,to:41,spoken:'You do not need to promise an instant transformation. You need a clear next step that the team can actually support.',camera:'Hold framing and give the contrast a small pause'}, {from:41,to:45,spoken:'Which part of that process would you simplify first?',camera:'Direct address and a quiet closing hold'}],review:'Check source meaning, unsupported claims, spoken readability and a later timed read before recording'};
const newsletterSample={week:'Illustrative next week: Week +1, Monday–Sunday; no real send date',agenda:['A clearer project brief','A practical review checklist','An upcoming programme note whose date is unconfirmed'],subject:'Three practical ideas for your next project',preheader:'A clearer brief, a better handoff, and one useful checklist.',modules:[{heading:'Start with the useful question',body:'Before choosing a format, write down what a customer needs to understand. Keep the first draft focused on that question, then attach the facts that support the answer.',cta:'Read the briefing guide',link:'MOCK-LINK-GUIDE'},{heading:'Make review easy to act on',body:'A useful review names the exact passage, the supporting evidence and a bounded correction. Keep confirmed facts, judgement and open questions separate so the next person knows what to change.',cta:'View the review checklist',link:'MOCK-LINK-CHECKLIST'},{heading:'A programme note for later',body:'A fictional workshop introduction is available as an editorial idea. Its date, venue and registration destination remain unconfirmed, so hold any announcement until the owner supplies those details.',cta:'Programme details pending',link:null}],audience:'Synthetic opted-in audience only; suppression and consent require checks before any real campaign',linkStatus:'Mock reference IDs are placeholders; no destination has been verified',sendStatus:'Draft newsletter only; no scheduling, audience upload or email send'};
